local DailyOfferItem = Class('DailyOfferItem')
local DAILY_OFFER_TYE = {
    FREE = 0,
    DAILY = 1 ,
    WEEKLY = 2
}
function DailyOfferItem:__init()
    self.dailyOfferId = nil
    self.DailyOfferDialog = nil
end

function DailyOfferItem:__delete()
    self.dailyOfferId = nil
    self.DailyOfferDialog = nil
end

function DailyOfferItem:Awake()
end

function DailyOfferItem:Start()
    self:AddButtonClick()
end

function DailyOfferItem:AddButtonClick()
    SetButtonAction(self.controller.gameObject , function()
        if isNull(self.dailyOfferId) then
            return
        end

        ---@type DailyOfferDojo
        local dailyOfferDojo = StoreUtils.GetOverseaStoreComp():GetDailyOfferDataByDailyOfferId(self.dailyOfferId)
        if checkInt(dailyOfferDojo.isDraw) == 2 then
            GameUtils.Toast(localize("商品已售罄"))
            return
        end

        local requestFunc = function(dailyOfferId)
            GameUtils.Request(Interfaces.StoreDrawDailyOffer,{ dailyOfferId = dailyOfferId }, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    return
                end
                GoodsUtils.DrawRewards(checkTable(response.data.rewards), true)
                xRecord.record("5-015", string.format("click_pack_%d", checkInt(dailyOfferDojo.dailyOfferId)))
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards } })
                if self.DailyOfferDialog then
                    self.DailyOfferDialog:Request()
                end
            end)
        end

        --- 策划需求点击具体项 领取具体的奖励
        if checkInt(dailyOfferDojo.currentStock) > 0 and checkInt(dailyOfferDojo.isDraw) == 1 then
            requestFunc(self.dailyOfferId)
        else
            if dailyOfferDojo:IsGoodExchange() then
                ---@type ServerDifferenceMgr
                local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
                local currrency = Constants.Currency.FreeDiamondId
                local price = 0 
                for goodsId, v in pairs(dailyOfferDojo.prices) do
                    price = v.current
                    currrency = checkInt(goodsId) 
                    break
                end
                ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                    currency = currrency,
                    current = price,
                }, function(isSuccess)
                    isSuccess = checkBool(isSuccess)
                    if not isSuccess then
                        return
                    end
                    ----请求兑换的逻辑
                    GameUtils.Request(Interfaces.OverseaMallDailySpecialBuy,{
                        productId  = dailyOfferDojo.dailyOfferId,
                        currency = currrency,
                        num = 1,
                    }, function(request,response)
                        if checkInt(response.errCode) == 0 then
                            local oneReawards = response.data.rewards  or {}
                            local rewards = clone(oneReawards)
                            rewards[#rewards+1] = {
                                goodsId = currrency ,
                                num = -price,
                                productId = checkNumber(dailyOfferDojo.dailyOfferId)
                            }
                            GoodsUtils.DrawRewards(rewards)
                            if #oneReawards > 0 then
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = oneReawards, cb = function()
                                    self.DailyOfferDialog:Request()
                                end  } })
                            else 
                                self.DailyOfferDialog:Request()
                            end
                        end
                    end )
                end)
            else 
                -- 当周卡不存在
                local SDKService = import('Game.Entry.SDKService')
                SDKService:GetInstance():PayMoney({
                    productId = dailyOfferDojo.productId,
                    channelProductId = dailyOfferDojo.channelProductId,
                    productDesc = localize("每日特惠"),
                    payAmount = dailyOfferDojo.price,
                    data = dailyOfferDojo
                })
            end     
        end
    end)

end
---更新限时特惠红点
function DailyOfferItem:UpdateTimeLimitDailyRedPoint()
    local redPoint = 0
    local dailyOfferData = OverseaStoreMgr:GetTimeLimitDailyData()
    for i = 1 , #dailyOfferData -1 do 
        local v = dailyOfferData[i]
        if checkInt(v.isDraw) == 1 then
            redPoint = 1
            break
        end
    end    
    GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaStoreTimeLimitDaily, redPoint)
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaStoreTimeLimitDaily )
end
---@param dailyOfferId number
---@param DailyOfferDialog DailyOfferDialog
function DailyOfferItem:RefreshDailyOfferUI(dailyOfferId , DailyOfferDialog)
    self:UpdateTimeLimitDailyRedPoint()
    self.dailyOfferId = dailyOfferId
    self.DailyOfferDialog = DailyOfferDialog
    ---@type DailyOfferDojo
    local dailyOfferDojo = StoreUtils.GetOverseaStoreComp():GetDailyOfferDataByDailyOfferId(dailyOfferId)
    -- 当存在周卡的时候
    local weeklyDojo = StoreUtils.GetOverseaStoreComp():GetDailyOfferWeeklyDojo()
    local CfUtils = CfUtils
    ---@type DailyOfferVo
    local dailyOfferVo = CfUtils.GetCfVo(AutoIds.IdSetting4040,"DailyOfferVo",dailyOfferId)
    if dailyOfferVo.giftType == DAILY_OFFER_TYE.FREE then
        for i = 1 , 2 do
            print(table.serialize(dailyOfferVo.rewards))
            local goodsId = dailyOfferVo.rewards[i].goodsId
            local num = dailyOfferVo.rewards[i].goodsNum
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local GoodNode = self["GoodNode" .. i]
            ---@type GoodNodeMB
            local goEnv = CfUtils.GetLuaScr(GoodNode, "Game.Behaviours.GoodNodeMB")
            goEnv:SetClickButtonAction(function()
                if num > 0 then
                    if isTable(vo) then
                        GameUtils.ShowCommonTipsBoard(GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                    end
                end
            end)
            goEnv:Reload({ goodsId = goodsId,
                           isShowNo = true, text = 'x' ..num
            })
        end
        CfUtils.FillText(self.StockNum.gameObject , string.format("%d/%d",dailyOfferDojo.currentStock,dailyOfferDojo.stock))
        local isHaveDraw = checkInt(dailyOfferDojo.isDraw) == 2
        KTool.SetActive(self.FinishGroup , isHaveDraw)
        local redPoint  = self.PriceLabel.transform:Find("redPoint")
        if isNotNull(redPoint) then
            KTool.SetActive(redPoint, (not isHaveDraw))
        end
    elseif dailyOfferVo.giftType == DAILY_OFFER_TYE.DAILY then
        for i = 1 , 2 do
            local goodsId = dailyOfferVo.rewards[i].goodsId
            local num = dailyOfferVo.rewards[i].goodsNum
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local GoodNode = self["GoodNode" .. i]
            ---@type GoodNodeMB
            local goEnv = CfUtils.GetLuaScr(GoodNode, "Game.Behaviours.GoodNodeMB")
            goEnv:SetClickButtonAction(function()
                if num > 0 then
                    if isTable(vo) then
                        GameUtils.ShowCommonTipsBoard(GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                    end
                end
            end)
            goEnv:Reload({ goodsId = goodsId,
                           isShowNo = true, text = 'x' ..num
            })
        end
        local UISwitchText = CS.Game.Native.Common.UISwitchText
        ---@type Game.Native.Common.UISwitchText
        local StockNumParent = self.StockNum.transform.parent:GetComponent(typeof(UISwitchText))
        if weeklyDojo:GetLeftSecond() > 0 and checkInt(dailyOfferDojo.stock) > 0  then
            CfUtils.FillText(self.StockNum.gameObject , string.format("%d/%d",dailyOfferDojo.currentStock,1))
            if not isNull(StockNumParent) then
                StockNumParent.Status = 2
            end
        else
            CfUtils.FillText(self.StockNum.gameObject , string.format("%d/%d",dailyOfferDojo.currentStock,1))
            if not isNull(StockNumParent) then
                StockNumParent.Status = 1
            end
        end
        --CfUtils.FillText(self.StockNum , string.format("%d/%d",dailyOfferDojo.currentStock ,dailyOfferDojo.stock))
        if dailyOfferDojo:IsGoodExchange() then
            local currency = Constants.Currency.FreeDiamondId
            local num = 0 
            for goodsId, v in pairs(dailyOfferDojo.prices) do
                num = v.current
                currency =  goodsId
                break
            end
            local goodsPath = GoodsConfMgr:GetInstance():GetPhotoPathById(currency)
            CfUtils.FillImage(self.ImgIcon.gameObject , goodsPath)
            KTool.SetActive(self.ImgIcon.gameObject  ,true) 
            CfUtils.FillText(self.PriceLabel ,num)
        else
            KTool.SetActive(self.ImgIcon.gameObject  ,false)
            CfUtils.FillText(self.PriceLabel ,CfUtils.GetDisplayPrice(dailyOfferDojo.price , dailyOfferDojo.channelProductId))
        end
        KTool.SetActive(self.FinishGroup , (checkInt(dailyOfferDojo.isDraw) == 2 or checkInt(dailyOfferDojo.currentStock) == 0))
        if checkInt(dailyOfferDojo.isDraw)  >= 1 or checkInt(dailyOfferDojo.currentStock) == 0 then
            if  checkInt(dailyOfferDojo.isDraw) == 2 then
                KTool.SetActive(self.PriceLabel , true)
                KTool.SetActive(self.DrawLabel , false)
            else 
                KTool.SetActive(self.DrawLabel , true)
                KTool.SetActive(self.PriceLabel , false)
                KTool.SetActive(self.ImgIcon.gameObject  ,false) 
            end
            
        else
            KTool.SetActive(self.DrawLabel , false)
            KTool.SetActive(self.PriceLabel , true)
        end
    end
end

